import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"周易尚氏學 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"周易尚氏學 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"classics/shangshi/014.md","filePath":"classics/shangshi/014.md"}'),s={name:"classics/shangshi/014.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>卦上下皆陽。一陰止於內。故曰小畜。畜止也。太玄擬之曰斂。雲陽氣大滿於外。微陰小斂於內。是其義也。旁通豫坤為雲。上下皆坤爻。故曰密雲。兌為雨。乃兌雨前遇巽風。為風吹散。雲過日出。故不雨也。兌為西。伏坤為我。乾為郊。故曰自我西郊。言密雲起自西郊。過而不留也。舊解多從虞翻。以半坎為雲。既曰半坎。於密義似不合也。人知坎為雲。不知坤亦為雲。易林困之泰雲。陰雲四方。日在中央。以泰上坤為雲也。人知坎為雨。不知兌亦為雨。上系雲。潤之以風雨。風謂巽。雨謂兌也。睽上九往遇雨。亦以兌為雨。</p><p>彖曰。小畜。柔得位。而上下應之。曰小畜。健而巽。剛中而志行。乃亨。密雲不雨。尚往也。自我西郊。施未行也。</p><p>雲下降方為雨。尚往者。言云氣為風所吹。散而往上。故不能雨。又離火上炎。將密雲衝散。不能下落為雨。故膏澤未施也。上往純對下施言。</p><p>象曰。風行天上。小畜。君子以懿文德。</p><p>懿，美也。乾為德。離明。故曰文德。離明照天下。巽風散佈四方。故曰懿文德。</p><p>初九。復自道。何其咎。吉。</p><p>復來也。初為陽本位。陽來初。故曰復。來初當位。故曰復自道。乾為道也。初前臨重陽。行難。宜有咎。然當位有應。遁世無悶。故無咎也。</p><h3 id="象曰。復自道。其義吉也。" tabindex="-1">象曰。復自道。其義吉也。 <a class="header-anchor" href="#象曰。復自道。其義吉也。" aria-label="Permalink to “象曰。復自道。其義吉也。”">​</a></h3><p>義者宜也。言行誼如此。宜其吉也。</p><p>九二。牽復吉。</p><p>復來也。伏艮手。故曰牽復。玉篇雲。牽速也。禮學記君子之教喻也。道而不牽。姤九三象雲。其行次且。行未牽也。皆訓奉為速。牽復者。速來也。言來居二得中也。若作陽復解。則九二失位。何復之有。又按九二失位無應。承乘皆陽。本不吉。茲曰吉者。徒以得中也。</p><h3 id="象曰。牽覆在中。亦不自失也。" tabindex="-1">象曰。牽覆在中。亦不自失也。 <a class="header-anchor" href="#象曰。牽覆在中。亦不自失也。" aria-label="Permalink to “象曰。牽覆在中。亦不自失也。”">​</a></h3><p>二雖不當位而在中。故吉。清儒多從虞翻。以五牽二。令二變陰應五為說。若然。則各卦非先變既濟。不能說也。惑亂後學。莫此為甚。失佚古通。速復故曰不自佚。言不自安逸也。</p><p>九三。輿說輹。夫妻反目。</p><p>輹正義作輻。而馬融以為車下縛。鄭玄訓為伏兔。則皆作輹。茲從馬鄭。伏坤為輿。伏震為輹。輹者輿所恃以行。乃輿在內而輹在外。則輿脫輹矣。乾為夫。坤為妻。巽得坤之初爻。故亦為妻。巽為白眼。卦二至上。正反巽。白眼與白眼相反。是反目也。三上無應。下乘重陽。故有是象。震輹象失傳。左傳僖十五年。筮遇歸妹之睽。曰車脫其輹。夫歸妹之睽。即震變離。震變離則震象毀。故曰車脫其輹。輹伏兔。上承車箱。下軛車軸。子夏傳釋名。皆以輹為車屐。因在箱下。有若履然。故左傳以震為輹。屐。震象也。虞氏改作腹。非也。</p><h3 id="象曰。夫妻反目。不能正室也。" tabindex="-1">象曰。夫妻反目。不能正室也。 <a class="header-anchor" href="#象曰。夫妻反目。不能正室也。" aria-label="Permalink to “象曰。夫妻反目。不能正室也。”">​</a></h3><p>坎為室。坎伏不見。故曰不能正室。言夫無如妻何也。</p><p>六四。有孚。血去惕出。無咎。</p><p>四卦主。五陽孚之。故曰有孚。釋文血馬雲當作恤。憂也。是馬以血為恤之省文。而荀爽王弼等。直讀為血。非也。坎為恤為惕。乃坎伏不見。故曰恤去惕出。言不憂懼也。四當位有應。上承重陽。故無咎。</p><h3 id="象日。有孚惕出。上合志也。" tabindex="-1">象日。有孚惕出。上合志也。 <a class="header-anchor" href="#象日。有孚惕出。上合志也。" aria-label="Permalink to “象日。有孚惕出。上合志也。”">​</a></h3><p>上謂五上。五上皆陽。四承之。陰遇陽得類。故曰合志。此與升初六之上合志義同也。巽為志。易林姤之小過。心志不親。小過中爻正反巽。故心志不親。又蒙之升。成子得志。亦以升下巽為志。蓋心志在內。而巽為伏。故巽為志。</p><p>九五。有孚攣如。富以其鄰。</p><p>孚謂孚於四。四卦主。陽喜陰。故下三陽亦孚於四。攣引也。牽也。言陽皆孚四。有若牽引連接也。九家謂五孚下三爻。虞翻強命二變謂五孚二。並非。陽於陽不孚也。五天子位。巽為利。五乘之。故富。伏震為鄰。富以其鄰。言五之所以富。以鄰於四也。九家謂五以四陰作財。與下三陽共之。故曰不獨富。深得經旨。</p><h3 id="象曰。有孚攣如。不獨富也。" tabindex="-1">象曰。有孚攣如。不獨富也。 <a class="header-anchor" href="#象曰。有孚攣如。不獨富也。" aria-label="Permalink to “象曰。有孚攣如。不獨富也。”">​</a></h3><p>不獨義見前。</p><p>上九。既雨既處。尚德載。婦貞厲。月幾望。君子徵兇。</p><p>雲上往。至上九而極。兌為雨。兌覆向下。是雨已下施也。故曰既雨。既已也。詩召南江有汜。其後也處。毛傳。處止也。既處者。言雨已止也。德者雨澤也。尚德載。言雨澤下降。乾旋坤受。地得載其德澤也。巽為婦。柔之為道不利遠。高處在上。非婦德所宜。故婦貞得此爻者。厲也。兌為月。互離為日。月西日東。相望。幾。孟、荀作既。孟雲。即望十六日也。納甲法。十五日夜乾象。月盈甲。十六日平明巽象。月退辛。上九處巽之終。正既望也。既望則陽將消。又三無應。故徵兇。自兌月象失傳。小畜歸妹中孚之月幾望。舊解皆以坎為月。豈知易之言月。十九皆謂兌。說卦象。與經所用象。不盡同也。易林復之臨雲。月出平地。以臨上坤為地。下兌為月也。又家人之小畜雲。杲杲白日。為月所食。以小畜互離為日。兌為月。兌月侵入離體之半。故曰為月所食。兌月象。後惟邵子知之。而清易家皆不信。豈知邵子所用。與易林合。與易合哉。</p><h3 id="象曰。既雨既處。德積載也。君子徵兇。有所疑也。" tabindex="-1">象曰。既雨既處。德積載也。君子徵兇。有所疑也。 <a class="header-anchor" href="#象曰。既雨既處。德積載也。君子徵兇。有所疑也。" aria-label="Permalink to “象曰。既雨既處。德積載也。君子徵兇。有所疑也。”">​</a></h3><p>吳先生曰。古得德同字。德積載。即雨澤得為大地所載也。巽為疑。下無應。陽遇陽。故疑。</p><p>站長：孟、荀可能是指孟喜和荀爽，他們是西漢時期的易學家。應該當作「既望」，巽也為月始缺，如小畜「既雨既處...月既望」同理。</p>',31)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
